const $=id=>document.getElementById(id);
let state={albums:[],n:3,gap:8,color:'#e7e0d0',title:'MY HEAVY ROTATION',labels:false};
try{const saved=JSON.parse(localStorage.getItem('sleeve-room-v1'));if(saved&&Array.isArray(saved.albums))state={...state,...saved,n:[3,4,5].includes(saved.n)?saved.n:3};}catch{}
let toastTimer,dragIndex=null;
function toast(message){$('toast').textContent=message;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',4500);}
function save(){try{localStorage.setItem('sleeve-room-v1',JSON.stringify(state));}catch{toast('브라우저 저장 공간이 부족합니다. 현재 작업은 PNG로 저장해 주세요.');}}
function render(){const grid=$('grid');grid.replaceChildren();grid.style.gridTemplateColumns=`repeat(${state.n},1fr)`;grid.style.gap=state.gap+'px';$('poster').style.background=state.color;$('poster').style.color=state.color==='#222623'?'#e7e0d0':'#272b23';$('posterTitle').textContent=state.title||'MY HEAVY ROTATION';$('count').textContent=`${state.albums.length} / ${state.n**2} RECORDS`;
for(let i=0;i<state.n**2;i++){const slot=document.createElement('div');slot.className='slot';const album=state.albums[i];if(album){slot.draggable=true;const img=document.createElement('img');img.src=album.url;img.alt=album.title;img.addEventListener('error',()=>{img.alt='이미지를 불러올 수 없습니다';},{once:true});slot.append(img);const remove=document.createElement('button');remove.className='remove';remove.textContent='×';remove.ariaLabel=album.title+' 삭제';remove.onclick=()=>{state.albums.splice(i,1);update();};slot.append(remove);if(state.labels){const label=document.createElement('div');label.className='album-label';label.textContent=album.title;slot.append(label);}slot.ondragstart=e=>{dragIndex=i;e.dataTransfer.setData('text/plain',String(i));e.dataTransfer.effectAllowed='move';};slot.ondragend=()=>dragIndex=null;
slot.tabIndex=0;slot.title='드래그로 이동 · Alt + 방향키로 순서 변경';slot.onkeydown=e=>{if(e.altKey&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const diff={ArrowLeft:-1,ArrowRight:1,ArrowUp:-state.n,ArrowDown:state.n}[e.key];const target=i+diff;if(target>=0&&target<state.albums.length){const [a]=state.albums.splice(i,1);state.albums.splice(target,0,a);update();grid.children[target].focus();}}};
}else{slot.classList.add('empty');const number=document.createElement('span');number.textContent=String(i+1).padStart(2,'0');slot.append(number);}slot.ondragover=e=>e.preventDefault();slot.ondrop=e=>{e.preventDefault();if(dragIndex===null)return;const [album]=state.albums.splice(dragIndex,1);state.albums.splice(Math.min(i,state.albums.length),0,album);dragIndex=null;update();};grid.append(slot);}
document.querySelectorAll('[data-n]').forEach(b=>b.classList.toggle('active',+b.dataset.n===state.n));document.querySelectorAll('[data-color]').forEach(b=>b.classList.toggle('active',b.dataset.color===state.color));$('gapValue').textContent=state.gap+' px';}
function update(){render();save();}
$('title').value=state.title;$('gap').value=state.gap;$('labels').checked=state.labels;
$('title').oninput=e=>{state.title=e.target.value;update();};$('gap').oninput=e=>{state.gap=+e.target.value;update();};$('labels').onchange=e=>{state.labels=e.target.checked;update();};
document.querySelectorAll('[data-n]').forEach(b=>b.onclick=()=>{const n=+b.dataset.n;if(state.albums.length>n*n){toast(`현재 ${state.albums.length}장이 있어요. ${n*n}장 이하로 줄인 뒤 변경해 주세요.`);return;}state.n=n;update();});document.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>{state.color=b.dataset.color;update();});
$('clear').onclick=()=>{if(state.albums.length&&confirm('담아 둔 앨범을 모두 비울까요?')){state.albums=[];update();}};
function add(album){if(state.albums.length>=state.n**2){toast('그리드가 가득 찼어요. 더 큰 그리드를 선택해 주세요.');return;}if(state.albums.some(a=>a.id===album.id)){toast('이미 담은 앨범이에요.');return;}state.albums.push(album);update();}
$('upload').onchange=async e=>{for(const file of e.target.files){if(state.albums.length>=state.n**2){toast('그리드가 가득 찼어요.');break;}if(!file.type.startsWith('image/'))continue;if(file.size>20*1024*1024){toast('20MB 이하 이미지를 선택해 주세요.');continue;}try{const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas');canvas.width=canvas.height=600;const ctx=canvas.getContext('2d'),side=Math.min(bitmap.width,bitmap.height);ctx.drawImage(bitmap,(bitmap.width-side)/2,(bitmap.height-side)/2,side,side,0,0,600,600);bitmap.close();add({id:crypto.randomUUID(),title:file.name.replace(/\.[^.]+$/,''),artist:'내 컬렉션',url:canvas.toDataURL('image/jpeg',.85)});}catch{toast(file.name+' 파일을 읽을 수 없어요.');}}e.target.value='';};
async function loadImage(url){const response=await fetch(url,{signal:AbortSignal.timeout(30000)});if(!response.ok)throw Error('이미지 응답 오류');const blob=await response.blob();return createImageBitmap(blob);}
$('download').onclick=async()=>{if(!state.albums.length){toast('앨범을 먼저 담아 주세요.');return;}const button=$('download');button.disabled=true;button.textContent='이미지 만드는 중…';const snapshot=JSON.parse(JSON.stringify(state));let images=[];try{const settled=await Promise.allSettled(snapshot.albums.map(a=>loadImage(a.url)));images=settled.filter(r=>r.status==='fulfilled').map(r=>r.value);if(settled.some(r=>r.status==='rejected'))throw Error('일부 커버를 가져오지 못했어요. 해당 커버를 직접 업로드한 뒤 저장해 주세요.');await document.fonts.ready;const canvas=document.createElement('canvas');canvas.width=1800;canvas.height=1980;const ctx=canvas.getContext('2d'),pad=80,gap=snapshot.gap*3,area=1640,cell=(area-gap*(snapshot.n-1))/snapshot.n;ctx.fillStyle=snapshot.color;ctx.fillRect(0,0,1800,1980);ctx.fillStyle=snapshot.color==='#222623'?'#e7e0d0':'#272b23';ctx.font='20px "DM Sans",sans-serif';ctx.fillText('SLEEVE ROOM / PERSONAL COLLECTION',pad,57);ctx.textAlign='right';ctx.fillText('VOL. 001',1720,57);ctx.textAlign='left';ctx.fillRect(pad,78,1640,2);for(let i=0;i<snapshot.n**2;i++){const x=pad+(i%snapshot.n)*(cell+gap),y=120+Math.floor(i/snapshot.n)*(cell+gap);if(images[i]){const image=images[i],side=Math.min(image.width,image.height);ctx.drawImage(image,(image.width-side)/2,(image.height-side)/2,side,side,x,y,cell,cell);if(snapshot.labels){ctx.fillStyle='#111c';ctx.fillRect(x,y+cell-42,cell,42);ctx.fillStyle='#fff';ctx.font='18px "Noto Sans KR",sans-serif';ctx.save();ctx.beginPath();ctx.rect(x+8,y+cell-42,cell-16,42);ctx.clip();ctx.fillText(snapshot.albums[i].title,x+8,y+cell-14);ctx.restore();}}else{ctx.fillStyle='#80808022';ctx.fillRect(x,y,cell,cell);}}ctx.fillStyle=snapshot.color==='#222623'?'#e7e0d0':'#272b23';ctx.font='700 63px "Noto Sans KR",sans-serif';ctx.fillText(snapshot.title||'MY HEAVY ROTATION',pad,1870,1640);ctx.font='20px "DM Sans",sans-serif';ctx.fillText('A SOUNDTRACK TO MY DAYS. / SELECTED BY YOU',pad,1920);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('이미지를 만들지 못했어요.');const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='sleeve-room.png';link.click();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('PNG를 저장했어요.');}catch(error){toast(error.message||'저장하지 못했어요. 다시 시도해 주세요.');}finally{images.forEach(image=>image.close());button.disabled=false;button.textContent='↗ PNG 저장';}};
render();
window.sleeveRoom = { add, toast };